-- Update provider institution details
UPDATE provider_institution SET
    intake_date = 'June, September',
    updated_at = NOW()
WHERE cricos_provider_code = '03844J';

UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <div> <p>The Bachelor of Business equips students with contemporary business knowledge, analytical skills, and practical capabilities to succeed in a rapidly changing global economy.</p><p>This program offers students the flexibility to specialise in one of three high-growth areas: AI Management, Hospitality Management, and Enterprise Management Systems (EMS), reflecting emerging industry demands and evolving workforce needs.</p><p>The AI Management stream develops graduates who can harness artificial intelligence and data-driven tools to enhance strategic decision-making and organisational innovation.</p> </div> </div><div> <div> <div> <details> <div> <div> <div> <div> <div> <p>The Hospitality Management stream prepares students for dynamic service industries by combining customer experience design, operations management, and sustainable business practices.</p><p>The Enterprise Management Systems stream focuses on integrating technology with business processes, enabling graduates to optimise enterprise performance through digital transformation and systems thinking.</p><p>Across all specialisations, the program embeds digital literacy, ethical leadership, sustainability, and innovation as core capabilities. Students engage in experiential learning, industry projects, and real-world problem-solving, ensuring they graduate work-ready and future-focused.</p><p>The program aligns with national and global trends shaping business education, producing graduates who can lead, adapt, and drive transformation in diverse organisational contexts.</p> </div> </div> </div> </div> </div> </details> </div> </div> </div><h4>Course Learning Outcomes</h4><div> <div> <ul> <li> <span> <i></i> </span> <span>A broad understanding of key business disciplines, including accounting, marketing, supply chain, trade, and human resource management.</span> </li> <li> <span> <i></i> </span> <span>A sound understanding of key issues in conducting business across borders, cultures, legal systems, and time zones.</span> </li> <li> <span> <i></i> </span> <span>Cognitive and technical skills to analyse business data, solve problems, and think critically in international contexts.</span> </li> <li> <span> <i></i> </span> <span>Communication skills to work effectively in diverse teams and present information clearly in professional and academic contexts.</span> </li> <li> <span> <i></i> </span> <span>Apply knowledge and skills with initiative and judgement in planning, problem-solving, and decision-making.</span> </li> <li> <span> <i></i> </span> <span>Solve complex professional issues in diverse contexts.</span> </li> <li> <span> <i></i> </span> <span>Apply knowledge and skills responsibly and collaboratively in professional and international contexts.</span> </li> </ul> </div> </div><h4>Career Pathways</h4><div> <div> <p>The demand for business professionals has been extremely consistent over the past decade, offering lots of diverse career opportunities for business graduates.</p><p>Be confident to take on roles in management, marketing, business analysis, or accounting. Have a look at some career salaries below.</p><h3>Potential Careers</h3><ul><li>Business Development Manager<br/>Avg. Salary: $115,697</li><li>Relationship Manager<br/>Avg. Salary: $110,000<ul><li>Business Consultant<br/>Avg. Salary: $105,000</li></ul></li></ul><p><br/>All salaries, sourced from <a href="https://au.talent.com/salary">talent.com</a>, are accurate as of September 2024.</p> </div> </div><div> <div> <h3>Complimentary Student Memberships</h3> </div> </div><div> <div> <p></p><p><strong>ACS Membership</strong></p><p><a href="https://www.aisa.org.au/">ACS</a> is the professional association for Australia’s technology sector and the largest community with 48,000+ members. All AIBI HE students are eligible to sign up for their free ACS membership.</p> </div> </div><h4>Course Subjects</h4><div> <div> <p>The table below provides essential information for each core subject, code and title, description, and assessment tasks.</p><p>The workload is the same for all subjects:<br/>3 timetabled hours per week (lectures and tutorials) and 9 personal hours of study for a total of 12 hours per week.</p> </div> </div><h4>Year 1 (Level 100)</h4><div> <div> <div> <details> <summary> <span><p> BUS100 Accounting for Business </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to business accounting, an essential component of every successful business. They consider the role of accounting within the global business context and develop an understanding of the key fundamental accounting frameworks used.</p><p>Students are introduced to the accounting cycle and acquire key accounting skills and knowledge to enable them to examine the three key financial and accounting statements for all businesses: the balance sheet, income statement, and cash flow statement. In addition, they are introduced to the principles of budgeting, cost-volume analysis, and the concepts and theories of capital investment.</p><p>Furthermore, students will investigate the concept and role of ethical and corporate governance specifically in the area of financial business management. They will also be introduced to contemporary technological developments including distributed ledger systems such as Bitchain.</p><p>Assessment<br/>Tutorial Quizzes, Mid-trimester examination, Final examination.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS101 Business Information Systems </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>The subject provides students with an introduction and broad overview of the application of information technology (IT) to the management of information in organisations, and the role of the IT professional in developing and implementing IT-based solutions to information problems across a range of areas related to general business activities and specific functions, such as supply chain management, e-commerce, customer relationship management and security.</p><p>Consideration of the organisational framework for IT and IT professional practice will be set within the broader business context. The opportunities, problems and risks associated with IT will be examined, together with their implications for organisational strategy and operations.</p><p>Assessment<br/>Tutorial participation, Case studies, Quizzes, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS103 Introduction to International Business </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject is designed to introduce students to the issues involved in undertaking business in the global marketplace.</p><p>It examines why businesses engage in international trade and business and considers the role that economics, politics, culture and ethics play in the decision to operate internationally. In addition to reviewing the arguments for and against globalisation, the unit looks at how organisations evaluate, plan, and undertake international engagement and expansion in a global context.</p><p>Particular attention is given to the appropriate means for engaging in international trade and expansion given the nature of and circumstances facing the organisation.</p><p>Students are introduced to concepts of international financing, marketing and human resource management.</p><p>Assessment<br/>Tutorial participation, Case study, Essay, Group project</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS104 Business Marketing </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with the fundamentals of marketing theory and practice within the global business environment.</p><p>Students will learn how to interpret the role of business marketing, and to analyse markets and market characteristics. They are introduced to and apply contemporary marketing theories and practices.</p><p>They examine the key concepts of consumer behaviour and the factors that influence consumer demand; what people buy and how businesses respond to this demand.</p><p>Furthermore, the unit explores how international businesses are developing their competitive edge as they face emerging challenges and issues in a global marketplace that is influenced by digital, social and visual media.</p><p>The unit concludes with students examining how businesses integrate ethical, sustainable and socially responsible practices within their marketing strategies.</p><p>Assessment<br/>Quizzes, Group research presentations and Reflective journals, Case study</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS105 Communications </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> This subject provides students with an introduction to communications in a business environment. An essential skill of any successful professional in today’s competitive business environment is the ability to communicate: to understand and be understood, both within the organisation and externally with suppliers, customers, and a range of stakeholders. Business organisations today are seeking well-rounded employees who can demonstrate strong communication skills across a range of mediums. Throughout this subject, students develop their ability to identify, gather, and present information in a range of oral, written, and visual contexts, using digital and non-digital channels. There is a focus on mobile communication and its effect on contemporary business practices, with students exploring how globalisation and social media are changing business communication. The subject concludes with students examining some of the emerging technologies that have the potential to reshape business communication in the near future. </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS110 Quantitative Methods for Business </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to statistics. The ability to accurately collect, analyse, and interpret data, is an essential skill in businesses today.</p><p>In this unit, students are introduced to basic statistical methods and practice and their role in business and organisational decision making. The unit explores various data types and methods of sampling and collection.</p><p>It examines graphical and numerical statistical methods and introduces concepts such as probability, inference, distributions, estimation, and hypothesis testing.</p><p>Assessment<br/>Tutorial quizzes, Practical exercises, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick one general elective as part of their study:</p><p>BUS102 Introduction to Enterprise Management Systems</p><p>CYB101 Introduction to Cyber Security</p><p>ICT125 Programming Fundamentals</p><p>ICT130 Networking Essentials</p><p>ICT140 Systems and Database</p><p>MGT101 Operations and Logistics Management</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick three of the following electives as part of their level 100 studies:</p><p>BUS102 Introduction to Enterprise Management Systems<br/>CYB101 Introduction to Cyber Security<br/>ICT125 Programming Fundamentals<br/>ICT130 Networking Essentials<br/>ICT140 Systems and Database<br/>MGT101 Operations and Logistics Management</p> </div> </div> </div> </div> </div> </details> </div> </div> </div><h4>Year 2 (Level 200)</h4><div> <div> <div> <details> <summary> <span><p> BUS201 Data Analytics </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to data analytics. In this unit, students will lay the groundwork necessary for today’s data analysis practices including data process chain, data warehousing, descriptive and predictive analyses, Business Intelligence process flow, and Data Mining.</p><p>In addition, students will build a solid foundation in various Business Intelligence frameworks, architectures, applications, tools, and management practices.</p><p>Students will further develop the essential knowledge to elaborate on the trends and implications of traditional, modern and next-generation data analytics solutions.</p><p>Through real-world case studies, students will apply critical thinking skills to develop data analytics solutions that map out business metrics, employing a data-driven approach and business intelligence tools and platforms used in international business and cybersecurity contexts.</p><p>Assessment<br/>Quizzes, Case study, Mid-trimester Exam, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS205 Business Research Methods </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject broadens students’ knowledge and skills relating to business research methods that could be employed to assist managers in making important business decisions.</p><p>Students are introduced to the process of business research necessary to address different types of business problems. Students gain understanding on quantitative and qualitative research methods, identify business problems, design, and apply suitable research methodology to provide relevant information for management decisions.</p><p>The subject will discuss sampling, measurement, data collection methods, collation, analysis, and reporting. Finally, the presentation of research findings will be discussed.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT202 International Strategic Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an overview of Strategic Management in an international context.</p><p>It covers the key concepts and theories in the field and how they can be used to interpret and evaluate business situations in domestic and international settings.</p><p>The aim of the unit is to show how management strategy can help companies create and capture value.</p><p>The central objective will be to understand differences in profitability across firms in the global economy, placing special attention on the factors that explain why some firms achieve above-average performance.</p><p>The focus of the unit is on understanding the drivers of sustainable competitive advantage, in particular in a global context, and an understanding of the relationship between internal and external factors.</p><p>Assessment<br/>Case study, Scenario analysis and report, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT205 Entrepreneurship and Innovation </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to entrepreneurship and innovation.</p><p>The subject encourages entrepreneurial behaviour through the introduction of the principles of entrepreneurship, the process of creativity and innovation through the human-centred design methodology, and the impact of this process on the success of new enterprise creation.</p><p>On completion of this unit, students will have an increased understanding of entrepreneurship, entrepreneurs and the significance of innovation in small and medium-sized enterprises (SMEs).</p><p>The associated skills and techniques acquired in this unit will provide a strong foundation for both new product/service development and the launch of an entrepreneurial or corporate new venture.</p><p>Assessment<br/>Presentations, Interview, Participation, Presentation</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT208 Organisational Behaviour and Change Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to organisational behaviour and change management applicable to the dynamic global business environment.</p><p>Organisational behaviour can be described as the study of human behaviour at the individual group and corporate level.</p><p>Students will gain of organisations by examining personal characteristics, drivers of behaviours, group dynamics, and the associated change management processes that organisations can use to maximise their effectiveness.</p><p>Assessment<br/>Quizzes &amp; Participation, Group Report and Presentation, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick four of the following electives as part of their level 200 studies:</p><p>BUS203 Business Process Management<br/>BUS204 Accounting Systems<br/>MGT201 International Law and Politics<br/>MGT203 Production and Service Delivery Systems<br/>MGT204 Inventory and Asset Management Systems<br/>MGT206 Business Law<br/>CYB210 Applied Cryptography<br/>CYB225 Secure Coding<br/>CYB230 Network and Web Security<br/>CYB235 Cloud Security<br/>CYB250 Cybercrime, Cyberlaw and Cyber-ethics</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick four of the following electives as part of their level 200 studies:</p><p>BUS203 Business Process Management<br/>BUS204 Accounting Systems<br/>MGT201 International Law and Politics<br/>MGT203 Production and Service Delivery Systems<br/>MGT204 Inventory and Asset Management Systems<br/>MGT206 Business Law<br/>CYB210 Applied Cryptography<br/>CYB225 Secure Coding<br/>CYB230 Network and Web Security<br/>CYB235 Cloud Security<br/>CYB250 Cybercrime, Cyberlaw and Cyber-ethics</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 3 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick four of the following electives as part of their level 200 studies:</p><p>BUS203 Business Process Management<br/>BUS204 Accounting Systems<br/>MGT201 International Law and Politics<br/>MGT203 Production and Service Delivery Systems<br/>MGT204 Inventory and Asset Management Systems<br/>MGT206 Business Law<br/>CYB210 Applied Cryptography<br/>CYB225 Secure Coding<br/>CYB230 Network and Web Security<br/>CYB235 Cloud Security<br/>CYB250 Cybercrime, Cyberlaw and Cyber-ethics</p> </div> </div> </div> </div> </div> </details> </div> </div> </div><h4>Year 3 (Level 300)</h4><div> <div> <div> <details> <summary> <span><p> BUS301 Business Strategy </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>BUS301 Business SThis subject provides students with the foundations of business strategy.</p><p>With the advent of an interdependent global marketplace, modern business engagement is complex and constantly being re-invented.</p><p>The purpose of this subject is to equip students with the ability to approach complex business problems from the cross-functional and multidimensional perspective of the CEO.</p><p>To develop and maintain a successful sustainable corporate strategy, there must first be an understanding of the links between the wider macro influences, our own industry nuances and the assets we control internally.</p><p>Starting with an understanding of the historical development of strategy, this unit will investigate the journey from the work of Sun Tsu to Mintsberg Strategic Thinking Schools through to more recent concepts of Total Quality Management, Business Process Re-engineering and onwards.</p><p>While the environment of our businesses was focused on our local domestic markets for many decades, it is now essential to be aware of the threat of global competitors.</p><p>Case analysis is used extensively to link concepts and frameworks to real-world examples. Group work engages students in the challenges of interpersonal communication, task allocation, coordination and control.</p><p>Assessment<br/>Quiz, Essay, Case study, Group reporttrategy</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS303 International Marketing </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to the development of marketing strategies for organisations operating in the international business environment.</p><p>Emphasis is placed on analysing trends in the international marketing environment, identifying business opportunities and adapting standard marketing concepts to the diverse social, cultural, political and economic situations found in international markets.</p><p>Attention is also given to the link between marketing and fulfilment mechanisms and customer service and the international economic, political, legal and cultural environmental influences on marketing planning.</p><p>Students will be required to assess the impact of media on marketing strategy and to analyse marketing opportunities in international contexts.</p><p>Assessment<br/>Tutorial participation, Report 1&amp;2, Group presentation</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT301 Global Supply Chain Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> This unit provides students with an introduction to global supply chain management. Supply chain management is the management of relationships in the network of organisations, from end customers through original suppliers, using key cross-functional business processes to create value for customers and other stakeholders. The ability to accurately forecast demand for products and services is central to supply chain management. The aim of this unit is to debate the fundamental processes of supply chain management – demand forecasting and inventory optimisation – in terms of demand-driven forecasting, the dynamic balancing of customer demand and systems capability. While the unit gives an overview of supply-driven inventory management, it does not go into the details of warehousing or inventory control. Rather, the emphasis is on a review of demand-driven forecasting and how inventory management is shaped by demand forecasting. The overall aim is to assess a methodology that combines data, analytics and an understanding of contemporary supply chain process optimisation. Assessment Tutorial participation, Quizzes, Case study, Project </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT303 Business Leadership in a Global Context </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to key leadership issues and challenges business managers face in an international environment.</p><p>Rather than concentrating on theories of leadership, the subject focuses on the development of practical leadership skills.</p><p>Particular emphasis is given to cross-cultural management, workplace diversity, managing a distributed, virtual and multicultural workforce, and culture-based tactics for international negotiations.</p><p>The subject encourages students to consider the concept of leadership through the lens of managers who are required to work in local and global environments simultaneously, examining the intersections of leadership and management and the role of multicultural competence in creating competitive advantage.</p><p>Assessment<br/>Tutorial participation, Case Study 1, Critique, Case Study 2</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick one of the following electives as part of their level 300 studies:</p><p>BUS302 Sales and Logistics Systems<br/>BUS304 Procurement Management Systems<br/>BUS305 International Trade and Finance<br/>MGT302 Extended Enterprise Management Systems<br/>MGT304 Human Management Capital Systems<br/>CYB310 Digital Investigations and Forensics<br/>CYB340 Cyber-Physical Systems and IoT Security<br/>CYB345 Penetration Testing<br/>CYB350 Cyber Security Operations<br/>CYB355 Cybergovernance Risk and Compliance<br/>CYB358 Project Management</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick one of the following electives as part of their level 300 studies:</p><p>BUS302 Sales and Logistics Systems<br/>BUS304 Procurement Management Systems<br/>BUS305 International Trade and Finance<br/>MGT302 Extended Enterprise Management Systems<br/>MGT304 Human Management Capital Systems<br/>CYB310 Digital Investigations and Forensics<br/>CYB340 Cyber-Physical Systems and IoT Security<br/>CYB345 Penetration Testing<br/>CYB350 Cyber Security Operations<br/>CYB355 Cybergovernance Risk and Compliance<br/>CYB358 Project Management</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CAP301 Capstone Project </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>An important element of success in business organisations today is the ability to undertake research-based projects.</p><p>Such projects might seek to describe an organisational environment, identify issues, or suggest solutions to an identified problem relevant to the program they have been enrolled in.</p><p>This subject builds upon students’ previous study in their program and offers an opportunity to focus on a relevant area of interest through a formal research-related project.</p><p>Students in this subject will learn about the principles of effective research and conduct a short research project on a topic of interest based upon or influenced by their areas of interest within their program.</p><p>The subject is in two parts. In the first part, students either learn about the fundamentals of organisational research or have a refresher course to ensure that all students in the unit have the same level of preparation.</p><p>They also work with the subject coordinator to develop an agreed research topic. In the second part, they conduct their major project.</p><p>During this period, they will also meet and consult regularly with the unit coordinator to discuss their project progress.</p><p>Assessment<br/>Participation, Research Report and Presentation Part 1&amp;2</p><p>*Please note that this capstone project is worth 20 credits.</p> </div> </div> </div> </div> </div> </details> </div> </div> </div>',
    total_course_duration = '3 years',
    offshore_tuition_fee = 65000,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h3>Eligibility Criteria</h3><p>Age at Time of Course Commencement</p><p>• 18 or older</p><h3>Education</h3><p>• Year 12 Completion (or equivalent). <span>Requirements differ per country.</span></p><p><strong>English Proficiency:</strong></p><p>• IELTS: 6.0 Overall (no band less than 5.5, or equivalent)<br/>• PTE: 52 Overall (no band less than 50, or equivalent)</p><p>For more information on admissions criteria, visit our <a href="https://aibi.edu.au/how-to-apply/">Applying to AIBI HE</a> page.</p>',
    apply_form = 'https://aibi.edu.au/bachelor-of-business/',
    updated_at = NOW()
WHERE cricos_course_code = '0102178';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <div> <p>The Bachelor of Cyber Security (BCS) at AIBI Higher Education provides students with the practical skills and knowledge to defend organisations against modern cyber threats.</p><p>This degree offers a solid foundation for a career in the growing cyber security sector. Students will also be exposed to highly useful subjects focusing on soft skills and human factors.</p><h3>Learning Outcomes</h3><ul><li>Develop a deep understanding of the concepts and technologies related to information security.</li><li>Learn about encryption, firewalls, network security, ethical hacking, and various threat intelligence strategies.</li><li>Gain hands-on experience in security operations, risk management, incident response, and business continuity planning.</li></ul> </div> </div><div> <div> <p><a href="/bachelor-of-cyber-security/#career-pathways">Career Pathways</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-cyber-security/#subjects">Subjects</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-cyber-security/#entry-details">Entry Details</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-cyber-security/#how-to-apply">How to Apply</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-cyber-security/#faq">FAQs</a></p> </div> </div><h4>Career Pathways</h4><div> <div> <p>With the cyber security industry booming, there’s huge demand, great pay, and tons of really exciting career pathways for cyber security graduates!</p><p>You’ll be ready for exciting roles in security ops, penetration testing, threat intelligence, and more. See below for some industry salary stats.</p><h3>Potential Careers</h3><ul><li>Cyber Security Analyst<br/>Avg. Salary: $111,694</li><li>Penetration Tester Avg. Salary: $125,000</li><li>Security Consultant Avg. Salary: $140,000</li></ul><p>All salaries, sourced from talent.com, are accurate as of September 2024.</p> </div> </div><h4>Course Subjects</h4><div> <div> <p>The table below provides essential information for each core subject, code and title, description, and assessment tasks.</p><p>The workload is the same for all subjects:<br/>3 timetabled hours per week (lectures and tutorials) and 9 personal hours of study for a total of 12 hours per week.</p> </div> </div><h4>Year 1 (Level 100)</h4><div> <div> <div> <details> <summary> <span><p> CYB101 Introduction to Cyber Security </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides a holistic approach to cyber security. After discussing the threat landscape, including common cyber threats as well as cybercriminal categories and motivations, it examines the devastating impact that cybercrime can have on individuals and organisations through case studies.</p><p>Cyber hygiene and organisational security principles are then introduced to help individuals and businesses remain safe in the digital world. The unit concludes by addressing cybersecurity governance.</p><p>It presents various risk assessment methodologies, risk management frameworks, mitigation strategies as well as the ethical and legal aspects of cyber security.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Cyber Hygiene Project, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS105 Communications </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to communications in a business environment. An essential skill of any successful professional in today’s competitive business environment is the ability to communicate: to understand and be understood, both within the organisation and externally with suppliers, customers and a range of stakeholders.</p><p>Business organisations today are seeking well-rounded employees who can demonstrate strong communication skills across a range of mediums. This is particularly true across the areas of international business, enterprise management systems and cyber security.</p><p>Throughout this subject, students develop their ability to identify, gather and present information in a range of oral, written and visual contexts, using digital and non-digital channels. There is a focus on mobile communication and its effect on contemporary business practices with students exploring how globalisation and social media are changing business communication.</p><p>The subject concludes with students examining some of the emerging technologies that have the potential to reshape business communication in the near future.</p><p>Assessment Tasks:<br/>Presentations, Written Reports, Group Oral Presentation</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS110 Quantitative Methods for Business </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>The subject provides students with a background on data analysis techniques and statistical concepts. It explores various methods of data collection and sampling with an emphasis on the question of data quality. It examines graphical and numerical statistical methods and introduces concepts such as probabilities, models, distributions, inference, Bayesian statistics, estimation, and hypothesis testing.</p><p>Besides the direct benefit of mastering basic statistical notions and techniques, the unit also provides a foundation to tackle data analytics and artificial intelligence concepts, which are playing an increasingly important role in areas such as international business, enterprise management systems and cyber security.</p><p>This subject relies on a hands-on approach and involves the use of dedicated computer software to analyse data coming from different fields and involved in various scenarios. Throughout the unit, students are prompted to critically assess the pertinence of the methods used.</p><p>Assessments Tasks:<br/>Student Engagement, Tests, Data Analysis Assignment</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> ICT125 Programming Fundamentals </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject introduces programming using Python. It discusses fundamental programming concepts such as variables, functions, recursion, data structures, and objects in an interactive way, using Jupyter Notebook.</p><p>Each week, students further develop their problem-solving skills and algorithmic capabilities. They do so by tackling practical issues, many of them relevant to cyber security and implementing their approach in a Python program.</p><p>The importance of ethics and sound software engineering practices, in particular documentation, testing and debugging are continuously reinforced throughout the entire unit.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Programming Assignments, Practical Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> ICT130 Networking Essentials </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with essential data communications and networking concepts. Students develop a sound foundation for each layer of the OSI model, including their architecture, workflow, properties, purpose, and functions.</p><p>They also explore the principles and mechanisms required to transmit data across a network starting from the physical layer, all the way to the top, the software platform.</p><p>They examine the workflow executed during this transmission, implement and configure various network protocols within a simulated environment using industry-known networking tools.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Practical Assignments, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> ICT140 Systems and Database Design </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject introduces students to the fundamental principles of database systems, including how organisations structure and manage corporate information within the data processing lifecycle.</p><p>Students translate business requirements into conceptual data models using data modelling tools and techniques, which are then transformed into relational databases, applying normalisation techniques.</p><p>Students manipulate data and logical structures in a relational database management system using SQL, a domain-specific query language. The concepts and issues related to contemporary database technologies with their applications and information security are also examined to underpin current industry practices.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Data Modelling and SQL Assignment, Practical Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick two of the following electives as part of their level 100 studies:</p><p>BUS100 Accounting for Business<br/>BUS101 Business Information Systems<br/>BUS102 Introduction to Enterprise Management Systems<br/>BUS103 Introduction to International Business<br/>BUS104 Business Marketing<br/>MGT101 Operations and Logistics Management</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick two of the following electives as part of their level 100 studies:</p><p>BUS100 Accounting for Business<br/>BUS101 Business Information Systems<br/>BUS102 Introduction to Enterprise Management Systems<br/>BUS103 Introduction to International Business<br/>BUS104 Business Marketing<br/>MGT101 Operations and Logistics Management</p> </div> </div> </div> </div> </div> </details> </div> </div> </div><h4>Year 2 (Level 200)</h4><div> <div> <div> <details> <summary> <span><p> CYB210 Applied Cryptography </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> This subject provides students with the necessary background to understand modern cryptographic primitives such as hash functions, symmetric-key ciphers, public-key cryptography, and digital signatures. It tackles elementary cryptanalysis techniques before addressing protocols such as key exchange, key management, secret sharing, zero knowledge proof, etc. Students then learn how these primitives and protocols are used in concrete applications such as data protection, identity management, access control, blockchain, cryptocurrencies, electronic voting, etc. Assessment Tasks: Student Engagement, Tests, Catch the Flag Assignment, Practical Examination </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS201 Data Analytics </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject introduces students to the fundamental concepts underlying data analytics and Big Data. Students build a solid foundation in various frameworks, techniques and tools to perform descriptive, and more importantly predictive modelling.</p><p>The subject also addresses the crucial question of business reporting with an emphasis on visualisation techniques.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Case Study, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB225 Secure Coding </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject further develops the student’s knowledge and programming skills by exposing them to a new language (Rust), while focusing on security issues.</p><p>It investigates real-life examples where the exploitation of software vulnerabilities has led to resounding disasters. The unit also addresses common software vulnerabilities, as well as the techniques and tools to detect and fix them.</p><p>The subject then moves to best practices regarding the software development life cycle, introducing DevSecOps and insisting on the critical importance of integrating security concerns at each stage of the process.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Group Programming Assignments, Practical Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB230 Network and Web Security </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject builds on networking essentials to provide students with the knowledge and skills required for network security, including wireless networks, as well as web security.</p><p>It focuses on specific threats, common vulnerabilities and the risks that they create in the context of interconnected computing devices.</p><p>It addresses a range of strategies, techniques and tools to mitigate those risks, such as firewalls, VPN, Access Control List (ACL), zero trust, end-point security, etc. It also tackles the deployment of a simple Intrusion Detection System (IDS) through the network.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Networking Group Assignments, Practical Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB235 Cloud Security </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject introduces cloud computing with an emphasis on cloud security. It covers the foundations of cloud computing, including distributed systems, concurrency and virtualisation, before addressing the different models, architectures and technologies involved in cloud computing.</p><p>The subject focuses next on important operations and practicals: data migration, identity and access management, etc.</p><p>The final part is entirely dedicated to cloud security, taking into account governance aspects, guidelines and standards, as well as technical elements to address vulnerabilities, data security and privacy risks in the cloud.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Consultancy Report, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB250 Cybercrime, Cyberlaw and Cyber-ethics </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an extensive theoretical and cross-disciplinary background in cyber security, specifically in the areas of crime, ethics and regulations.</p><p>It presents the transnational nature of cybercrime and students explore how national laws, regulations and international treaties help deal with cybercrime in cyberspace.</p><p>This subject prompts students to evaluate the effectiveness of these cyber laws against cybercrime in an attempt to bring cybercriminals to justice.</p><p>Finally, students examine cybersecurity issues and emerging global technologies within a business context through the lens of ethical and legal considerations.</p><p>Assessment Tasks:<br/>Student engagement, Tests, Legal group report, Final examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick two of the following electives as part of their level 200 studies:</p><p>BUS203 Business Process Management<br/>BUS205 Research Methods<br/>MGT201 International Law and Politics<br/>MGT202 International Strategic Management<br/>MGT203 Production and Service Delivery Systems<br/>MGT204 Inventory and Asset Management Systems<br/>MGT205 Entrepreneurship and Innovation<br/>MGT206 Business Law<br/>MGT208 Organisational Behaviour and Change</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick two of the following electives as part of their level 200 studies:</p><p>BUS203 Business Process Management<br/>BUS205 Research Methods<br/>MGT201 International Law and Politics<br/>MGT202 International Strategic Management<br/>MGT203 Production and Service Delivery Systems<br/>MGT204 Inventory and Asset Management Systems<br/>MGT205 Entrepreneurship and Innovation<br/>MGT206 Business Law<br/>MGT208 Organisational Behaviour and Change</p> </div> </div> </div> </div> </div> </details> </div> </div> </div><h4>Year 3 (Level 300)</h4><div> <div> <div> <details> <summary> <span><p> CYB310 Digital Investigations and Forensics </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides an introduction to digital forensics processes, methods, techniques and tools.</p><p>The first part focuses on understanding the profession, the ethical requirements and the processes used to maintain the chain of custody.</p><p>The second part deals with the technical side of digital forensics, including how to acquire and recover data from a variety of sources.</p><p>The last part is dedicated to analysing and reporting evidence in a professional manner, for instance as an expert witness.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Data Recovery Assignment, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB340 Cyber Physical Systems and IoT Security </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject explores the concepts, tools and techniques for securing Cyber Physical Systems and IoT devices.</p><p>With the convergence of information technology and operational technology, the rapid growth, and the pervasive role of smart objects, security must be at the forefront of the mind when designing and implementing solutions.</p><p>This subject addresses all the elements necessary to create smart and secure connected objects: architecture, protocols, threats, vulnerabilities, and risks as well as the controls and countermeasures that can be applied to mitigate those risks.</p><p>This subject provides many examples such as automated vehicles, smart homes, smart cities, industrial controls and wearables.</p><p>Assessment Tasks:<br/>Student Engagement, IoT Implementation Project, Security Evaluation Report, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB345 Penetration Testing </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides an introduction to penetration testing also known as ethical hacking. Ethics and ethical behaviour play a central role.</p><p>Indeed, during the course of this subject, students gain the knowledge and hacking skills required to systematically search for potential vulnerabilities in software, protocols and systems.</p><p>Students are also taught how to report those vulnerabilities so that they can be fixed. As such, communication also plays a crucial role in this unit.</p><p>Assessment Tasks:<br/>Student Engagement, First CTF, Group CTF, Research and Presentation, Final CTF</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB350 Cyber Security Operations </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides a practical approach to security operations. It covers three main areas.</p><p>First, security architecture (seen as integrated into the overall Enterprise Architecture) addresses authentication, authorisation and access control models as well as security and privacy by design.</p><p>Second, we focus on managing day-to-day operations, including how to integrate old and new technologies, manage a SIEM and apply SOAR methodologies.</p><p>Third, we concentrate on dealing with a security incident, addressing business continuity, incident response plan, digital forensics and evidence management.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Incident Response Group Assignment, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB355 Cybergovernance Risk and Compliance </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides a hands-on introduction to cybersecurity management. It presents well-known cyber governance standards such as NIST CSF and ISO27001, covering a range of topics, including legal and ethical issues, regulatory requirements, the human factor and security culture, as well as policy development.</p><p>It also focuses on the notion of risk and discusses qualitative and quantitative risk assessment approaches such as risk matrices and the FAIR (Factor Analysis of Information Risk) methodology.</p><p>Emphasis is given throughout the unit on how to effectively communicate cybersecurity risks to senior audiences.</p><p>Assessment Tasks:<br/>Student Engagement, Tests, Security Maturity Assessment Group Project and Presentation, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB358 Project Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject is a theoretical introduction to the management of projects in Cyber Security. It aims at equipping students with a solid understanding of project management principles. It also presents contemporary project management techniques and tools.</p><p>It insists on the importance of understanding the context of an organisation prior to and during the implementation of the project.</p><p>It also aims to develop an understanding of the factors that make a project successful, including leadership, communication, business acumen, etc.</p><p>Assessment Tasks:<br/>Student Engagement, Test, Case Study, Final Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CYB360 Capstone Project </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>In this subject, a group of students work together as a team for a fictitious company called HACKME, over the course of one trimester.</p><p>HACKME faces a multiplicity of cybersecurity challenges, ranging from its people, culture, business processes and use of technology.</p><p>After a detailed introduction of the different facets of the company, students need to identify and select a practical and complex cybersecurity issue faced by HACKME and justify why it needs to be addressed, from a business point of view.</p><p>Students then plan and implement a comprehensive project in response to that issue, pulling together the knowledge and skills that they acquired in previously studied units.</p><p>Assessment Tasks:<br/>Project Pitch and Approval, Project Plan and Proposal, Project Update Report, Project Deliverables, Reflective Journal, Final Presentation</p><p>*Please note that this capstone project is worth 20 credits.</p> </div> </div> </div> </div> </div> </details> </div> </div> </div>',
    total_course_duration = '3 years',
    offshore_tuition_fee = 65000,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h3>Eligibility Criteria</h3><p>Age at Time of Course Commencement</p><ul><li>18 or older<br/>Education</li><li>Year 12 Completion (or equivalent). <span>Requirements differ per country.</span></li></ul><p><strong>English Proficiency:</strong></p><ul><li>IELTS: 6.0 Overall (no band less than 5.5, or equivalent)</li><li>PTE: 52 Overall (no band less than 50, or equivalent)</li></ul><p>For more information on admissions criteria, visit our <a href="https://aibi.edu.au/how-to-apply/">Applying to AIBI HE</a> page.</p><p>*Note: Students entering this course are required to have their own personal laptop with the following specifications:</p><ul><li>Minimum: 8th Gen Intel Core i5 or AMD Ryzen 5, 16GB of RAM and 512GB SSD of storage.</li><li>Recommended: 9th Gen Intel Core i7 or AMD Ryzen 7, 32GB of RAM and 1TB SSD of storage.</li></ul>',
    apply_form = 'https://aibi.edu.au/bachelor-of-cyber-security/',
    updated_at = NOW()
WHERE cricos_course_code = '112840F';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <div> <p>The Bachelor of Enterprise Management Systems (BEMS) at AIBI Higher Education teaches students how to choose, set up, and manage systems that improve business processes and data analysis.</p><p>With a focus on practical skills using industry-standard software and real-world case studies, this degree prepares graduates for a range of roles in different sectors.</p><p><strong>Learning Outcomes</strong></p><ul><li>Develop practical skills in using industry-standard software for managing business operations.</li><li>Gain experience through real-world case studies and guest lectures from industry professionals.</li><li>Prepare for diverse career opportunities in various sectors by learning essential management skills.</li></ul> </div> </div><div> <div> <p><a href="/bachelor-of-enterprise-management-systems/#career-pathways">Career Pathways</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-enterprise-management-systems/#subjects">Subjects</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-enterprise-management-systems/#entry-details">Entry Details</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-enterprise-management-systems/#how-to-apply">How to Apply</a></p> </div> </div><div> <div> <p><a href="/bachelor-of-enterprise-management-systems/#faq">FAQs</a></p> </div> </div><h4>Career Pathways</h4><div> <div> <p>As organisations increasingly rely on advanced systems for their operations, graduates of the Bachelor of Enterprise Management Systems can expect strong demand for their skills.</p><p>This degree opens doors to diverse career pathways in systems management, business analysis, data analytics, and IT consultancy. Check out the industry salary stats below.</p><p><strong>Potential Careers</strong></p><ul><li>Consultant Software Engineer<br/>Avg. Salary: $178,800</li><li>Business Analyst<br/>Avg. Salary: $113,622</li><li>System Analyst<br/>Avg. Salary: $110,988</li></ul><p>All salaries, sourced from <a href="https://au.talent.com/salary">talent.com</a>, are accurate as of September 2024.</p> </div> </div><div> <div> <h3>Complimentary Student Memberships</h3> </div> </div><div> <div> <p></p><p><strong>ACS Membership</strong></p><p><a href="https://www.aisa.org.au/">ACS</a> is the professional association for Australia’s technology sector and the largest community with 48,000+ members. All AIBI HE students are eligible to sign up for their free ACS membership.</p> </div> </div><h4>Course Subjects</h4><div> <div> <p>The table below provides essential information for each core subject, code and title, description, and assessment tasks.</p><p>The workload is the same for all subjects:<br/>3 timetabled hours per week (lectures and tutorials) and 9 personal hours of study for a total of 12 hours per week.</p> </div> </div><h4>Year 1 (Level 100)</h4><div> <div> <div> <details> <summary> <span><p> BUS101 Business Information Systems </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction and broad overview of the application of information technology (IT) to the management of information in organisations, and the role of the IT professional in developing and implementing IT-based solutions to information problems across a range of areas related to general business activities and specific functions, such as supply chain management, e-commerce, customer relationship management and security.</p><p>Consideration of the organisational framework for IT and IT professional practice will be set within the broader business context. The opportunities, problems and risks associated with IT will be examined, together with their implications for organisational strategy and operations.</p><p>Assessment<br/>Tutorial participation, Case studies, Quizzes, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS102 Introduction to Enterprise Management Systems </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an understanding of Enterprise Management Systems (EMS) and the associated issues of selecting, implementing and using these types of systems.</p><p>The unit introduces students to fundamental EMS concepts of transparency, real-time functioning and process orientation. Students will have the opportunity to gain “hands-on” practical experiences with EMS to reinforce how these types of systems are utilised to automate, integrate and manage an organisation’s business processes while at the same time reinforcing the theoretical concepts covered in this unit.</p><p>The objective of the unit is to provide students with sufficient knowledge of EMS so that they can appreciate the role of these systems and their functionality in supporting a company’s strategy and core business processes.</p><p>Assessment<br/>Quizzes, Case study, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS110 Quantitative Methods for Business </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to statistics. The ability to accurately collect, analyse, and interpret data, is an essential skill in businesses today.</p><p>In this unit, students are introduced to basic statistical methods and practice and their role in business and organisational decision-making. The unit explores various data types and methods of sampling and collection.</p><p>It examines graphical and numerical statistical methods and introduces concepts such as probability, inference, distributions, estimation, and hypothesis testing.</p><p>Assessment<br/>Tutorial quizzes, Practical exercises, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> ICT140 Database and Systems Design </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject introduces students to the fundamental principles of database systems, including how organisations structure and manage corporate information within the data processing lifecycle.</p><p>Students translate business requirements into conceptual data models using data modelling tools and techniques, which are then transformed into relational databases, applying normalisation techniques.</p><p>Students manipulate data and logical structures in a relational database management system using SQL, a domain-specific query language. The concepts and issues related to contemporary database technologies with their applications and information security are also examined to underpin current industry practices.</p><p>Assessment Tasks:<br/>Student engagement, Tests, Data modelling and SQL assignment, Practical examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT101 Operations and Logistics Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to operations and logistics management and examines key issues currently facing all service and manufacturing organisations when creating products and services.</p><p>The fundamentals of managing logistics have become a key advantage in the contemporary business context. A primary aim of the unit is to illustrate the principles involved in effectively creating value through using the techniques and tools of operations and logistics management.</p><p>Continuously improvement of operations and logistics management can help ensure the organisation’s long-term success.</p><p>After placing the activities required for the operations and logistics manager into a conceptual framework, the practical issues and difficulties in making operations and logistics decisions are examined, including operations and logistics strategy, planning and control, warehousing, transportation, e-commerce operations, and improvement activities.</p><p>Assessment<br/>Participation, Group presentation, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick three of the following electives as part of their level 100 studies:</p><p>BUS100 Accounting for Business<br/>BUS103 Introduction to International Business<br/>BUS105 Communications<br/>BUS104 Business Marketing<br/>CYB101 Introduction to Cyber Security<br/>ICT125 Programming Fundamentals<br/>ICT130 Networking Essentials<br/>ICT140 Systems and Database</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick three of the following electives as part of their level 100 studies:</p><p>BUS100 Accounting for Business<br/>BUS103 Introduction to International Business<br/>BUS105 Communications<br/>BUS104 Business Marketing<br/>CYB101 Introduction to Cyber Security<br/>ICT125 Programming Fundamentals<br/>ICT130 Networking Essentials<br/>ICT140 Systems and Database</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 3 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick three of the following electives as part of their level 100 studies:</p><p>BUS100 Accounting for Business<br/>BUS103 Introduction to International Business<br/>BUS105 Communications<br/>BUS104 Business Marketing<br/>CYB101 Introduction to Cyber Security<br/>ICT125 Programming Fundamentals<br/>ICT130 Networking Essentials<br/>ICT140 Systems and Database</p> </div> </div> </div> </div> </div> </details> </div> </div> </div><h4>Year 2 (Level 200)</h4><div> <div> <div> <details> <summary> <span><p> BUS201 Data Analytics </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to data analytics. In this unit, students will lay the groundwork necessary for today’s data analysis practices including data process chain, data warehousing, descriptive and predictive analyses, Business Intelligence process flow, and Data Mining.</p><p>In addition, students will build a solid foundation in various Business Intelligence frameworks, architectures, applications, tools, and management practices.</p><p>Students will further develop the essential knowledge to elaborate on the trends and implications of traditional, modern and next-generation data analytics solutions.</p><p>Through real-world case studies, students will apply critical thinking skills to develop data analytics solutions that map out business metrics, employing a data-driven approach and business intelligence tools and platforms used in international business and cybersecurity contexts.</p><p>Assessment<br/>Quizzes, Case study, Mid-trimester Exam, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS204 Accounting Systems </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides an understanding of the relevant business processes, transactions, information flows, internal controls and reports in accounting function within an enterprise management system’s (EMS) context.</p><p>It equips students with the knowledge and skills required to work with an accounting system software solution.</p><p>In addition, students will be able to understand and analyse the potential impact of emerging technologies such as block chains, distributed ledgers, artificial intelligence, forensic accounting and continuous reporting on accounting processes in enterprise management systems (EMS).</p><p>Assessment<br/>Quizzes, Project, Skills test, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS205 Business Research Methods </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject broadens students’ knowledge and skills relating to business research methods that could be employed to assist managers in making important business decisions.</p><p>Students are introduced to the process of business research necessary to address different types of business problems. Students gain understanding on quantitative and qualitative research methods, identify business problems, design, and apply suitable research methodology to provide relevant information for management decisions.</p><p>The subject will discuss sampling, measurement, data collection methods, collation, analysis, and reporting. Finally, the presentation of research findings will be discussed.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT202 International Strategic Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an overview of Strategic Management in an international context. It covers the key concepts and theories in the field and how they can be used to interpret and evaluate business situations in domestic and international settings.</p><p>The aim of the unit is to show how management strategy can help companies create and capture value. The central objective will be to understand differences in profitability across firms in the global economy, placing special attention on the factors that explain why some firms achieve above-average performance.</p><p>The focus of the unit is on understanding the drivers of sustainable competitive advantage, in particular in a global context, and an understanding of the relationship between internal and external factors.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT204 Inventory and Asset Management Systems </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to the key concepts of inventory and asset management systems. Inventory and asset management (IAM) processes are concerned with the storage and movement of materials within an organisation.</p><p>This unit, using appropriate EMS software, will review and elaborate on the IAM-related goods movements, related organisational data and master data. It will also examine IAM processes triggered by procurement, fulfilment and production operations. Inventory accuracy, and periodic and physical count processes will be examined.</p><p>The second part of the unit will focus on the key stages of the asset lifecycle. In particular, the unit will investigate the operational stage, debating the maintenance strategies and the related master data, and use the appropriate EMS software platform to simulate breakdown and planned maintenance workflows.</p><p>Assessment<br/>Quizzes, Software simulation, Case study, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT205 Entrepreneurship and Innovation </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to entrepreneurship and innovation. The subject encourages entrepreneurial behaviour through the introduction of the principles of entrepreneurship, the process of creativity and innovation through the human-centred design methodology, and the impact of this process on the success of new enterprise creation.</p><p>On completion of this unit, students will have an increased understanding of entrepreneurship, entrepreneurs and the significance of innovation in small and medium-sized enterprises (SMEs). The associated skills and techniques acquired in this unit will provide a strong foundation for both new product/service development and the launch of an entrepreneurial or corporate new venture.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick four of the following electives as part of their level 200 studies:</p><p>BUS203 Business Process Management<br/>MGT201 International Law and Politics<br/>MGT203 Production and Service Delivery Systems<br/>MGT204 Inventory and Asset Management Systems<br/>MGT205 Entrepreneurship and Innovation<br/>MGT206 Business Law<br/>MGT208 Organisational Behaviour and Change<br/>CYB210 Applied Cryptography<br/>CYB225 Secure Coding<br/>CYB230 Network and Web Security<br/>CYB235 Cloud Security<br/>CYB250 Cybercrime, Cyberlaw and Cyber-ethics</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick four of the following electives as part of their level 200 studies:</p><p>BUS203 Business Process Management<br/>MGT201 International Law and Politics<br/>MGT205 Entrepreneurship and Innovation<br/>MGT206 Business Law<br/>MGT208 Organisational Behaviour and Change<br/>CYB210 Applied Cryptography<br/>CYB225 Secure Coding<br/>CYB230 Network and Web Security<br/>CYB235 Cloud Security<br/>CYB250 Cybercrime, Cyberlaw and Cyber-ethics</p> </div> </div> </div> </div> </div> </details> </div> </div> </div><h4>Year 3 (Level 300)</h4><div> <div> <div> <details> <summary> <span><p> BUS301 Business Strategy </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with the foundations of business strategy. With the advent of an interdependent global marketplace, modern business engagement is complex and constantly being re-invented.</p><p>The purpose of this subject is to equip students with the ability to approach complex business problems from the cross-functional and multidimensional perspective of the CEO. To develop and maintain a successful sustainable corporate strategy, there must first be an understanding of the links between the wider macro influences, our own industry nuances, and the assets we control internally.</p><p>Starting with an understanding of the historical development of strategy, this unit will investigate the journey from the work of Sun Tsu to Mintzberg Strategic Thinking Schools through to more recent concepts of Total Quality Management, Business Process Re-engineering, and onwards. While the environment of our businesses was focused on our local domestic markets for many decades, it is now essential to be aware of the threat of global competitors.</p><p>Case analysis is used extensively to link concepts and frameworks to real-world examples. Group work engages students in the challenges of interpersonal communication, task allocation, coordination, and control.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS302 Sales and Logistics Systems </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This subject provides students with an introduction to sales and logistics systems.</p><p>In a globalised world, effective and efficient logistics and sales processes and related information management are critical to maintaining competitive advantage and sustained growth.</p><p>This unit equips me with an understanding of the concepts, transactions, processes, information flows and reports in the efficient and effective management of outbound logistics and sales processes in an enterprise-wide management system’s context.</p><p>It imparts students with the knowledge and skills to perform related information management transactions, processes and reports and covers topics such as pre-sales, sales order processing, delivery, transportation management and customer service in enterprise management system software solutions context.</p><p>It will allow students to understand and analyse the opportunities, impact and challenges in the exploitation and potential use of emerging management trends such as lean operations, analytics, Social media, automated warehousing and technology trends such as RFID, Blockchains, Internet of Things, Robotics and Artificial intelligence in managing logistics processes in business organisations.</p><p>Assessment<br/>Quizzes, Group project, Application test, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT301 Global Supply Chain Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>This unit provides students with an introduction to global supply chain management.</p><p>Supply chain management is the management of relationships in the network of organisations, from end customers through original suppliers, using key cross-functional business processes to create value for customers and other stakeholders.</p><p>The ability to accurately forecast demand for products and services is central to supply chain management.</p><p>The aim of this unit is to debate the fundamental processes of supply chain management – demand forecasting and inventory optimisation – in terms of demand-driven forecasting, the dynamic balancing of customer demand and systems capability.</p><p>While the unit gives an overview of supply-driven inventory management, it does not go into the details of warehousing or inventory control.</p><p>Rather, the emphasis is on a review of demand-driven forecasting and how inventory management is shaped by demand forecasting.</p><p>The overall aim is to assess a methodology that combines data, analytics and an understanding of contemporary supply chain process optimisation.</p><p>Assessment<br/>Tutorial participation, Quizzes, Case study, Project</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT302 Extended Enterprise Management Systems </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Organisations are extending their enterprise systems, beyond operational management, to a more high-level strategic focus both internally and externally to the organisation to support strategic decision-making and performance management.</p><p>This subject provides an overview of the characteristic domains such as functions, processes, performance reports and strategic features addressed by various extensions of enterprise management systems such as supply chain management (SCM), customer relationship management (CRM), product life cycle management (PLM), business process management (BPM) and business intelligence (BI).</p><p>It will introduce students to various contemporary technologies and emerging business trends and equip them with the knowledge and skills to evaluate the application of these technologies to extend the capabilities of enterprise management systems.</p><p>Assessment<br/>Class Assessment, Group Research Paper, Examination</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> CAP301 Capstone Project </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>An important element of success in business organisations today is the ability to undertake research-based projects.</p><p>Such projects might seek to describe an organisational environment, identify issues, or suggest solutions to an identified problem relevant to the program they have been enrolled in.</p><p>This subject builds upon students’ previous study in their program and offers an opportunity to focus on a relevant area of interest through a formal research-related project.</p><p>Students in this subject will learn about the principles of effective research and conduct a short research project on a topic of interest based upon or influenced by their areas of interest within their program.</p><p>The subject is in two parts. In the first part, students either learn about the fundamentals of organisational research or have a refresher course to ensure that all students in the unit have the same level of preparation.</p><p>They also work with the subject coordinator to develop an agreed research topic. In the second part, they conduct their major project.</p><p>During this period, they will also meet and consult regularly with the unit coordinator to discuss their project progress.</p><p>Assessment<br/>Participation, Research Report and Presentation Part 1&amp;2</p><p>*Please note that this capstone project is worth 20 credits.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 1 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick one of the following electives as part of their level 300 studies:</p><p>BUS303 International Marketing<br/>BUS304 Procurement Management Systems<br/>BUS305 International Trade and Finance<br/>MGT303 Business Leadership in a Global Context<br/>MGT304 Human Capital Management Systems<br/>MGT305 Sustainability in Business<br/>CYB310 Digital Investigations and Forensics<br/>CYB340 Cyber-Physical Systems and IoT Security<br/>CYB345 Penetration Testing<br/>CYB350 Cyber Security Operations<br/>CYB355 Cybergovernance Risk and Compliance<br/>CYB358 Project Management</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> Elective 2 </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Students must pick one of the following electives as part of their level 300 studies:</p><p>BUS303 International Marketing<br/>BUS304 Procurement Management Systems<br/>BUS305 International Trade and Finance<br/>MGT303 Business Leadership in a Global Context<br/>MGT304 Human Capital Management Systems<br/>MGT305 Sustainability in Business<br/>CYB310 Digital Investigations and Forensics<br/>CYB340 Cyber-Physical Systems and IoT Security<br/>CYB345 Penetration Testing<br/>CYB350 Cyber Security Operations<br/>CYB355 Cybergovernance Risk and Compliance<br/>CYB358 Project Management</p> </div> </div> </div> </div> </div> </details> </div> </div> </div>',
    total_course_duration = '3 years',
    offshore_tuition_fee = 65000,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><h3>Eligibility Criteria</h3><p>Age at Time of Course Commencement</p><ul><li>18 or older</li></ul><p><strong>Education</strong></p><ul><li>Year 12 Completion (or equivalent). <span>Requirements differ per country.</span></li></ul><p><strong>English Proficiency:</strong></p><ul><li>ELTS: 6.0 Overall (no band less than 5.5, or equivalent)</li><li>PTE: 52 Overall (no band less than 50, or equivalent)</li></ul><p>For more information on admissions criteria, visit our <a href="/how-to-apply/">Applying to AIBI HE</a> page.</p>',
    apply_form = 'https://aibi.edu.au/bachelor-of-enterprise-management-systems/',
    updated_at = NOW()
WHERE cricos_course_code = '0102179';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <div> <p>The Graduate Certificate of Business Administration at AIBI Higher Education is designed for professionals looking to strengthen their leadership, strategic thinking, and digital business acumen. This program equips students with the critical skills required to navigate complex business environments, drive innovation, and manage digital transformation in an evolving global market.</p> </div> </div><div> <div> <p><strong>Study Mode</strong><br/>On Campus, Online</p><p><strong>Campus Locations</strong><br/>Sydney, Melbourne, Brisbane, Perth, Online</p><p><strong>Student</strong><br/>Domestic, International</p><p><strong>Course Duration<br/></strong></p><div><div><p><span>Full time up to 0.75 years. Up to 1.5 years part time for <em><u>domestic students only</u>.</em></span></p></div></div><p><strong>Next Start Date<br/></strong>June &amp; September 2026</p> </div> </div><h4>Course Subjects</h4><div> <div> <p>Graduate Certificate of Business Administration</p> </div> </div><div> <div> <div> <details> <summary> <span><p> MKT601 Digital Marketing Management </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Explore the latest digital marketing trends, tools, and strategies to engage customers effectively. Learn how to leverage SEO, content marketing, social media, and analytics to drive business growth and brand awareness.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> MGT601 Organisational Behaviour </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Understand how individuals and groups behave within organizations and how leadership, culture, and motivation impact workplace dynamics. Develop skills to improve team performance and foster a positive work environment.</p><p> </p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS705 Managing in a Digital World </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Learn how digital technologies are reshaping businesses and management practices. This course covers digital transformation, emerging technologies, and strategies to navigate the fast-changing digital landscape.</p> </div> </div> </div> </div> </div> </details> <details> <summary> <span><p> BUS607 Business Model Innovation and Strategy </p></span> <span> <span><i></i></span> <span><i></i></span> </span> </summary> <div> <div> <div> <div> <div> <p>Explore how business models evolve and drive value in today’s dynamic environment. This course examines business model innovation, strategic implementation, and the influence of digital transformation and the Fourth Industrial Revolution. Learn to design, evaluate, and adapt business models through real-world examples and interactive case studies.</p> </div> </div> </div> </div> </div> </details> </div> </div> </div>',
    total_course_duration = '0.75 years',
    offshore_tuition_fee = 13500,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Eligibility Criteria: </strong><strong>Academic</strong></p><p><strong>Entry Option 1:</strong></p><p>You need to have an Australian Bachelor’s degree (AQF Level 7) or equivalent.</p><p><strong>Entry Option 2:</strong></p><p>Successful completion of a Diploma (AQF5) or Advanced Diploma (AQF6) qualification in a related discipline AND a minimum of three years full-time professional experience in related fields. Relevant work or professional experience may be demonstrated through means such as submission of a C.V or resume, reference letters, or other evidence.</p><p><strong>English</strong></p><p>If English is not your first language, you’ll need to demonstrate proficiency to enrol in this program. This can be met through prior studies or recognised English language tests.</p><p>Minimum English test results must be equivalent to Academic IELTS 6.0 (Speaking &amp; Writing: minimum band 6.0 and Reading &amp; Listening: minimum band 5.5) or equivalent.</p><p>Recognised English language proficiency exams include: Academic IELTS, PTE, TOEFL iBT, Cambridge English (CAE and CPE), and Duolingo for example.</p><p>English test results should be no older than two years since date of issuance.</p><p>Overseas applicants who have not studied at the secondary level in English, seeking admission into an AIBI HE course will need to demonstrate the required level of English proficiency.</p>',
    apply_form = 'https://aibi.edu.au/graduate-certificate-of-business-administration/',
    updated_at = NOW()
WHERE cricos_course_code = '117716C';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <div> <p>The <strong>Graduate Diploma of Business Administration (GDBA)</strong> at <strong>AIBI Higher Education</strong> is designed for aspiring business leaders and professionals seeking to enhance their strategic, leadership, and digital transformation capabilities. This program provides a strong foundation in business administration while equipping students with the skills to navigate complex and evolving business landscapes.</p> </div> </div><h4>Course Learning Outcomes</h4><div> <div> <p><strong>Throughout this program, you will:</strong></p> </div> </div><div> <div> <ul> <li> <span> <i></i> </span> <span>Critically evaluate and apply on contemporary business issues, theories, and practices in environments that are complex, uncertain, and digitally transformative.</span> </li> <li> <span> <i></i> </span> <span>Apply design thinking and analytics tools to develop innovative solutions to business problems that have a positive social, environmental, and economic impact over the long term.</span> </li> <li> <span> <i></i> </span> <span>Demonstrate authentic and inclusive leadership skills and technology expertise, with an understanding of the legal, ethical, social, economic, and environmental implications of digital transformation in national and global business contexts.</span> </li> <li> <span> <i></i> </span> <span>Apply advanced personal and interpersonal skills, including critical thinking, team collaboration, self-awareness, argument formulation, reflection, inclusion, consulting, and persuasive oral, written and professional communication, in a variety of team settings.</span> </li> <li> <span> <i></i> </span> <span>Integrate multidisciplinary theories and authentic practices, as well as maintain and expand the currency of professional workplace practices.</span> </li> </ul> </div> </div><h4>Course Subjects</h4><div> <div> <p>Graduate Diploma of Business Administration</p> </div> </div>',
    total_course_duration = '6 months',
    offshore_tuition_fee = 27000,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Eligibility Criteria</strong></p><p><strong>Academic</strong></p><p><strong>ENTRY OPTION 1:</strong></p><p>You need to have an Australian Bachelor’s degree (AQF Level 7) or equivalent.</p><p><strong>ENTRY OPTION 2:</strong></p><p>For those that don’t meet direct entry requirement above, we may consider a pathway through the <a href="https://aibi.edu.au/graduate-certificate-of-business-administration/">Graduate Certificate of Business Administration</a>.</p><p><strong>English</strong></p><p>If English is not your first language, you’ll need to demonstrate proficiency to enrol in this program. This can be met through prior studies or recognised English language tests.</p><p>Minimum English test results must be equivalent to Academic IELTS 6.0 (Speaking &amp; Writing: minimum band 6.0 and Reading &amp; Listening: minimum band 5.5) or equivalent.</p><p>Recognised English language proficiency exams include: Academic IELTS, PTE, TOEFL iBT, Cambridge English (CAE and CPE), and Duolingo for example.</p><p>English test results should be no older than two years since date of issuance.</p><p>Overseas and domestic applicants who have not studied at the secondary level in English, seeking admission into an AIBI HE course will need to demonstrate the required level of English proficiency.</p>',
    apply_form = 'https://aibi.edu.au/diploma-graduate-of-business-administration/',
    updated_at = NOW()
WHERE cricos_course_code = '117717B';
UPDATE courses SET
    course_description = '<h4>Course Overview</h4><div> <div> <p>A Gateway to Your Future in Tech</p><p>The Graduate Certificate of Information Technology is the ideal entry point for those looking to build foundational skills in IT or pivot into the fast-paced world of technology—no prior experience required.</p><p>Designed to be accessible and career-focused, this course introduces key areas of information technology and prepares students for further study or immediate entry into the tech industry. Whether you’re seeking to future-proof your career, gain a competitive edge, or take your first step toward an advanced qualification, this program offers a flexible and practical path forward.</p><p><strong>What You’ll Learn:</strong></p><p>Throughout the course, you will develop essential skills and knowledge in:</p><ul><li>Computer systems and network fundamentals</li><li>Cybersecurity principles and best practices</li><li>Data management and databases</li><li>IT project management and business systems</li></ul> </div> </div><h4>Course Subjects</h4><div> <div> <p>Graduate Certificate of Information Technology</p> </div> </div>',
    total_course_duration = '0.75 years',
    offshore_tuition_fee = 13500,
    enrolment_fee = 250,
    materials_fee = NULL,
    entry_requirements = '<h4>Entry Requirements</h4><p><strong>Eligibility Criteria</strong></p><p><strong>Academic</strong></p><p><strong>ENTRY OPTION 1:</strong></p><p>You need to have an Australian Bachelor’s degree (AQF Level 7) or equivalent.</p><p><strong>ENTRY OPTION 2:</strong></p><p>Successful completion of a Diploma (AQF5) or Advanced Diploma (AQF6) qualification in a related discipline AND a minimum of three years full-time professional experience in related fields. Relevant work or professional experience may be demonstrated through means such as submission of a C.V or resume, reference letters, or other evidence.</p><p><strong>English</strong></p><p>If English is not your first language, you’ll need to demonstrate proficiency to enrol in this program. This can be met through prior studies or recognised English language tests.</p><p>Minimum Academic IELTS Overall 6.5 with no band less than 6.0 (Speaking &amp; Writing: minimum band 6.0 and Reading &amp; Listening: minimum band 5.5) or equivalent.</p><p>Recognised English language proficiency exams include: Academic IELTS, PTE, TOEFL iBT, Cambridge English (CAE and CPE), and Duolingo for example.</p><p>English test results should be no older than two years since date of issuance.</p><p>Overseas applicants who have not studied at the secondary level in English, seeking admission into an AIBI HE course will need to demonstrate the required level of English proficiency.</p>',
    apply_form = 'https://aibi.edu.au/graduate-certificate-of-information-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '117781E';
